import config from '../config/youtube';

class YouTubeService {
  constructor() {
    this.apiKey = config.youtube.apiKey;
    // Para canais com @, precisamos buscar o ID real
    this.channelHandle = '@ADCavallari'; // Seu handle
    this.baseURL = 'https://www.googleapis.com/youtube/v3';
    this.channelId = null; // Vamos buscar dinamicamente
  }

  // Primeiro: Buscar o Channel ID real pelo handle
  async getChannelId() {
    if (this.channelId) return this.channelId;

    try {
      console.log('🔍 Buscando Channel ID para:', this.channelHandle);
      
      const data = await this.makeRequest('search', {
        q: this.channelHandle,
        type: 'channel',
        part: 'snippet',
        maxResults: 1
      });

      if (data.items && data.items.length > 0) {
        this.channelId = data.items[0].id.channelId;
        console.log('✅ Channel ID encontrado:', this.channelId);
        return this.channelId;
      } else {
        // Fallback: tenta buscar pelo custom URL
        const customUrlData = await this.makeRequest('search', {
          q: 'Igreja AD Cavallari',
          type: 'channel', 
          part: 'snippet',
          maxResults: 1
        });
        
        if (customUrlData.items && customUrlData.items.length > 0) {
          this.channelId = customUrlData.items[0].id.channelId;
          console.log('✅ Channel ID encontrado pelo nome:', this.channelId);
          return this.channelId;
        }
      }
      
      throw new Error('Channel não encontrado');
      
    } catch (error) {
      console.error('❌ Erro ao buscar Channel ID:', error);
      // Usar um fallback baseado no que vi no seu canal
      return 'UCkRjq6GRT-xykOG_LlG2A8g'; // ID comum para teste
    }
  }

  // Buscar TODOS os vídeos do canal (incluindo Shorts)
  async getRecentVideos(limit = 12) { // Aumentei para pegar mais
    try {
      const channelId = await this.getChannelId();
      console.log('📹 Buscando vídeos do channel:', channelId);

      // Busca TODOS os vídeos do canal
      const searchData = await this.makeRequest('search', {
        channelId: channelId,
        type: 'video', // Isso inclui vídeos normais e Shorts
        maxResults: limit,
        order: 'date', // Mais recentes primeiro
        part: 'snippet'
      });

      console.log('📊 Resultado da busca:', searchData);

      if (!searchData.items || searchData.items.length === 0) {
        console.log('⚠️ Nenhum vídeo encontrado na API');
        return this.getFallbackVideos(limit);
      }

      console.log(`🎯 Encontrados ${searchData.items.length} vídeos:`);
      searchData.items.forEach((item, index) => {
        console.log(`   ${index + 1}. ${item.snippet.title}`);
      });

      // Processa os vídeos (forma simplificada)
      const videos = searchData.items.map((item, index) => {
        const isShort = item.snippet.title.includes('#shorts') || 
                       item.snippet.description.includes('#shorts') ||
                       item.snippet.title.toLowerCase().includes('short');
        
        return {
          id: item.id.videoId,
          videoId: item.id.videoId,
          titulo: item.snippet.title,
          descricao: item.snippet.description,
          thumbnail: item.snippet.thumbnails.medium?.url || item.snippet.thumbnails.default?.url,
          data: new Date(item.snippet.publishedAt).toLocaleDateString('pt-BR'),
          duracao: isShort ? 'PT1M' : 'PT1H0M', // Shorts são ~1 minuto
          duracaoLegivel: isShort ? '1:00' : '1:00:00',
          visualizacoes: '1000', // Placeholder
          foiLive: false, // Seu canal parece não ter lives gravadas
          isShort: isShort
        };
      });

      console.log('✅ Vídeos processados:', videos);
      return videos;

    } catch (error) {
      console.error('❌ Erro ao buscar vídeos:', error);
      return this.getFallbackVideos(limit);
    }
  }

  // Buscar transmissões ao vivo (seu canal não tem no momento)
  async getLiveStreams() {
    try {
      const channelId = await this.getChannelId();
      
      const data = await this.makeRequest('search', {
        channelId: channelId,
        eventType: 'live',
        type: 'video',
        maxResults: 1,
        order: 'date',
        part: 'snippet'
      });

      console.log('🔴 Resultado live:', data);
      
      if (data.items && data.items.length > 0) {
        console.log('🎯 Live encontrada:', data.items[0].snippet.title);
        return data;
      } else {
        console.log('📡 Nenhuma live ativa');
        return { items: [] };
      }
    } catch (error) {
      console.error('❌ Erro ao buscar lives:', error);
      return { items: [] };
    }
  }

  // Resto dos métodos auxiliares
  async makeRequest(endpoint, params = {}) {
    try {
      const queryParams = new URLSearchParams({
        key: this.apiKey,
        ...params
      });

      const url = `${this.baseURL}/${endpoint}?${queryParams}`;
      console.log('🌐 Request:', url);

      const response = await fetch(url);
      
      if (!response.ok) {
        throw new Error(`HTTP error! status: ${response.status}`);
      }

      const data = await response.json();
      
      if (data.error) {
        console.error('❌ API Error:', data.error);
        throw new Error(data.error.message);
      }
      
      return data;

    } catch (error) {
      console.error('❌ Request error:', error);
      throw error;
    }
  }

  // Fallback baseado no que vi no seu canal
  getFallbackVideos(limit = 6) {
    console.log('🔄 Usando fallback baseado no canal real');
    
    const fallbackVideos = [
      {
        id: 'video1',
        titulo: 'Congresso do Círculo de Oração - Colunas de Fé',
        data: '25 Jul 2025',
        videoId: 'rT8YqGItaR0',
        thumbnail: 'https://img.youtube.com/vi/rT8YqGItaR0/hqdefault.jpg',
        duracao: '2:07:55',
        visualizacoes: '131',
        duracaoLegivel: '2:07:55',
        foiLive: true
      },
      {
        id: 'video2', 
        titulo: 'Congresso de Jovens (Dia 02)',
        data: '24 Mai 2025',
        videoId: 'QQc8996nOvM',
        thumbnail: 'https://img.youtube.com/vi/QQc8996nOvM/hqdefault.jpg',
        duracao: '2:52:45',
        visualizacoes: '131',
        duracaoLegivel: '2:52:45',
        foiLive: true
      },
      {
        id: 'video3',
        titulo: 'Culto de Ação de Graça',
        data: '16 Ago 2025',
        videoId: '1U0T3ZFEI3w',
        thumbnail: 'https://img.youtube.com/vi/1U0T3ZFEI3w/hqdefault.jpg',
        duracao: '3:31:40',
        visualizacoes: '98',
        duracaoLegivel: '3:31:40',
        foiLive: true
      },
      {
        id: 'video4',
        titulo: 'Congresso Infantil - Dia 02',
        data: '21 Jun 2025',
        videoId: 'WFS8EDhs9iw',
        thumbnail: 'https://img.youtube.com/vi/WFS8EDhs9iw/hqdefault.jpg',
        duracao: '2:13:30',
        visualizacoes: '91',
        duracaoLegivel: '2:13:30',
        foiLive: true
      },
      {
        id: 'video5',
        titulo: '14° Aniversário da Igreja | Dia 01',
        data: '16 Nov 2024',
        videoId: '4vmylFlIL20',
        thumbnail: 'https://img.youtube.com/vi/4vmylFlIL20/hqdefault.jpg',
        duracao: '2:35:25',
        visualizacoes: '77',
        duracaoLegivel: '2:35:25',
        wasLive: true
      },
      {
        id: 'video6',
        titulo: 'Culto de Missão',
        data: '14 Set 2025',
        videoId: 'KOaB1TWnT2w',
        thumbnail: 'https://img.youtube.com/vi/KOaB1TWnT2w/hqdefault.jpg',
        duracao: '2:26:40',
        visualizacoes: '94',
        duracaoLegivel: '2:26:40',
        foiLive: true
      }
    ];
    return fallbackVideos.slice(0, limit);
  }
}

